    ln = localname(el)
    if not ln:
        return False
    l = ln.lower()
    if 'lineseg' in l or 'linesegarray' in l or 'linesegarr' in l or 'linesegary' in l or 'lineseg' in l:
        return True
    if 'lineseg' in l or 'linesegarray' in l:
        return True
    if 'lineseg' in l:
        return True
    if 'linesegarray' in l:
        return True
    if 'lineseg' in l:
        return True
    # also catch camelCase variants by lower() check above
    if 'lineseg' in l or 'linesegarray' in l:
        return True
    if 'lineseg' in l:
        return True
    if 'linesegarray' in l:
        return True
    if 'lineseg' in l:
        return True
    if 'linesegarray' in l:
        return True
    # broader: any localname containing "lineseg" or "linesegarray"
