    # concatenate all hp:t text within the paragraph
    parts = []
    for t in p.xpath('.//hp:t', namespaces=ns):
        if t.text:
            parts.append(t.text)
    return ''.join(parts)


def set_paragraph_text_single_run(p, ns, new_text):
    # Put all content into first hp:t; remove other hp:t nodes' text.
    t_nodes = p.xpath('.//hp:t', namespaces=ns)
    if not t_nodes:
        # create run/t if absent
        run = etree.SubElement(p, f"{{{ns['hp']}}}run")
        run.set('charPrIDRef', '0')
        t = etree.SubElement(run, f"{{{ns['hp']}}}t")
        t.text = new_text
        return
    t_nodes[0].text = new_text
    for t in t_nodes[1:]:
        t.text = ''


def remove_layout_cache_from_paragraph(p):
    # Remove any descendant elements whose localname contains lineseg/linesegarray
    # but only those that are direct children or deeper; we remove the element itself.
