    # customer_name is split across runs: "고객사: Northwind " + "Retail"
    for p in section0_tree.xpath('.//hp:p', namespaces=ns):
        txt = paragraph_text(p, ns)
        if txt.startswith('고객사:'):
            # old customer name is everything after "고객사: "
            after = txt.split('고객사:', 1)[1]
            # preserve as-is trimmed left
            old['customer'] = after.strip()
            old['customer_parts'] = [t.text or '' for t in p.xpath('./hp:run/hp:t', namespaces=ns)]
            break

    for p in section0_tree.xpath('.//hp:p', namespaces=ns):
        txt = paragraph_text(p, ns)
        if txt.startswith('현 담당자:'):
            old['owner_name'] = txt.split('현 담당자:', 1)[1].strip()
            break

    for p in section0_tree.xpath('.//hp:p', namespaces=ns):
        txt = paragraph_text(p, ns)
        if txt.startswith('갱신 윈도우:'):
            old['renewal_window'] = txt.split('갱신 윈도우:', 1)[1].strip()
            break

    # pricing band in section0 table cell p id 31 likely just value
    for p in section0_tree.xpath('.//hp:p', namespaces=ns):
        txt = paragraph_text(p, ns).strip()
        if txt and txt != '가격 밴드' and txt and 'Standard-' in txt:
            old['band'] = txt
            break

    # escalation email in table
    for p in section0_tree.xpath('.//hp:p', namespaces=ns):
        txt = paragraph_text(p, ns).strip()
        if '@' in txt and 'example' in txt and txt.endswith('.example'):
            # but customer updates have asteron.example; old is northwind.example
            if txt != updates.get('escalation_email'):
                old['escalation_email'] = txt
                break

    for p in section0_tree.xpath('.//hp:p', namespaces=ns):
        txt = paragraph_text(p, ns)
        if txt.startswith('가격 메모:'):
            old['note'] = txt.split('가격 메모:', 1)[1].strip()
            break

    # renewal window also appears in section1 p id 44 with prefix '갱신 윈도우 확인:'

    return old


