    # Map from element to paragraph ancestor for quick mark
    for t in tree.xpath('.//hp:t', namespaces=ns):
        if t.text is None:
            continue
        if t.text == protected_exact_text:
            continue
        original = t.text
        new = original
        for old, newv in replacements.items():
            if old and old in new:
                new = new.replace(old, newv)
        if new != original:
            t.text = new
            # mark paragraph ancestor
            p = t.getparent()
            while p is not None and localname(p) != 'p':
                p = p.getparent()
            if p is not None:
                modified_paras.add(p)

    return modified_paras


def get_section_ns(tree):
    ns = {}
