    for k,v in (tree.getroot().nsmap or {}).items():
        if k is None:
            continue
        ns[k] = v
    # Ensure hp is present
    if 'hp' not in ns:
        ns['hp'] = 'http://www.hancom.co.kr/hwpml/2010/HWPML'
    return ns


def find_followup_paragraphs(section1_tree, ns):
    # Identify follow-up paragraphs as those whose concatenated text matches pattern "1." "2." "3." at start.
    ps = []
    for p in section1_tree.xpath('.//hp:p', namespaces=ns):
        txt = paragraph_text(p, ns).strip()
        if len(txt) >= 3 and txt[0].isdigit() and txt[1] == '.' and txt[2] == ' ':
            # Only the old follow-ups (alpha/beta/gamma) are in this form
            ps.append(p)
    return ps


def clone_paragraph_like(p):
    newp = deepcopy(p)
    # remove id attribute to avoid duplicate? but keep structure; IDs in hwpx may not be required.
    # We'll keep but adjust to next available integer if present.
    return newp


