        import re
        m = re.search(r'standalone=["\'](yes|no)["\']', first)
        if m:
            decl['standalone'] = (m.group(1) == 'yes')
    return decl


def main():
    with open(UPDATE_JSON, 'r', encoding='utf-8') as f:
        updates = json.load(f)

    with open(FOLLOWUPS_CSV, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = list(reader)
        followups = sorted(rows, key=lambda r: int(r['sequence']))
        followup_items = [r['item'] for r in followups]

    # Parse both sections
    s0_path, s1_path = SECTION_FILES
    s0_decl = read_xml_decl(s0_path)
    s1_decl = read_xml_decl(s1_path)

    s0 = parse_xml(s0_path)
    s1 = parse_xml(s1_path)

    ns0 = get_section_ns(s0)
    ns1 = get_section_ns(s1)

    protected = '이 부록 문단은 그대로 유지해야 합니다.'

    # Determine old values from section0 (and implicitly section1 for window)
    old = detect_old_values(s0, s1, ns0, updates)

    # Build replacements old->new
    # customer line is "고객사: <old>" (old may include space split); we'll replace old customer string anywhere
    replacements = {}

    # Customer name: old['customer'] like "Northwind Retail"; new is updates['customer'] (single)
    if old.get('customer') and updates.get('customer'):
        replacements[old['customer']] = updates['customer']
    # Also replace split pieces if needed (Northwind / Retail)
    if old.get('customer_parts') and updates.get('customer'):
        for part in old['customer_parts']:
            part_str = (part or '').replace('고객사:', '').strip()
            # filter empty and label remnants
            if part_str and part_str not in ('고객사:', '고객사'):
                # only replace if it's not the entire old customer already
                if part_str != old.get('customer'):
                    replacements[part_str] = updates['customer']

    if old.get('owner_name') and updates.get('owner_name'):
        replacements[old['owner_name']] = updates['owner_name']

    # renewal window old like "2025-04-01 ~ 2025-04-15" -> "{start} ~ {end}"
    new_window = None
    if updates.get('window_start') and updates.get('window_end'):
        new_window = f"{updates['window_start']} ~ {updates['window_end']}"

    if old.get('renewal_window') and new_window:
        replacements[old['renewal_window']] = new_window

    if old.get('band') and updates.get('band'):
        replacements[old['band']] = updates['band']

    if old.get('escalation_email') and updates.get('escalation_email'):
        replacements[old['escalation_email']] = updates['escalation_email']

    if old.get('note') and updates.get('note'):
        replacements[old['note']] = updates['note']

    modified_paras0 = replace_text_nodes(s0, ns0, replacements, protected)
    modified_paras1 = replace_text_nodes(s1, ns1, replacements, protected)

    # Replace follow-ups in section1
    modified_followups = replace_followups(s1, ns1, followup_items, protected)

    modified_paras1 |= modified_followups

    # Remove layout cache elements from modified paragraphs
    for p in list(modified_paras0):
        remove_layout_cache_from_paragraph(p)
    for p in list(modified_paras1):
        remove_layout_cache_from_paragraph(p)

    # Write back
    write_xml(s0, s0_path, s0_decl)
    write_xml(s1, s1_path, s1_decl)

    # Repack
    if os.path.exists(OUTPATH):
        os.remove(OUTPATH)

    with zipfile.ZipFile(OUTPATH, 'w', zipfile.ZIP_DEFLATED) as zout:
        mimetype_path = os.path.join(EXTRACT_DIR, 'mimetype')
        if os.path.exists(mimetype_path):
            zout.write(mimetype_path, 'mimetype', compress_type=zipfile.ZIP_STORED)

        for root, dirs, files in os.walk(EXTRACT_DIR):
            # replicate stable-ish order
            for fname in sorted(files):
                full = os.path.join(root, fname)
                arcname = os.path.relpath(full, EXTRACT_DIR)
                if arcname == 'mimetype':
                    continue
                zout.write(full, arcname)

    print('Wrote', OUTPATH)


if __name__ == '__main__':
    main()
